package app.zmby.data

/** Responsive LAN form; every asset is embedded and works offline. */
internal object ServerImportPage {
    val html = """

<!doctype html><html lang="zh"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>zmby 添加服务器与备份</title>
<style>
:root{color-scheme:dark;--bg:#0a0b0d;--card:#1a1b1f;--text:#fff;--sub:#a6a7af;--line:#ffffff18}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:16px/1.5 system-ui,sans-serif}button,input,textarea{font:inherit}button,a,input{touch-action:manipulation}button{cursor:pointer;min-height:44px;border:0;border-radius:24px;padding:10px 22px;background:linear-gradient(#ffffff36,#ffffff14);box-shadow:inset 0 1px #ffffff50;color:#fff;font-weight:600}button:disabled{opacity:.4;cursor:default}button:focus-visible,a:focus-visible{outline:3px solid white;outline-offset:4px}.primary{background:linear-gradient(#fff,#e4e5e9);color:#0a0b0d;width:100%;min-height:52px;font-weight:700}.secondary{background:#ffffff0c;box-shadow:inset 0 0 0 1px var(--line)}.small{padding:6px 14px;font-size:14px}header{max-width:1800px;margin:auto;padding:28px 36px;display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:20px}.brand{font-size:27px;font-weight:800;letter-spacing:-1px;display:flex;gap:12px;align-items:center}.brand svg{width:32px;height:32px}.tabs{display:flex;gap:4px;padding:5px;border-radius:30px;background:#0007;box-shadow:inset 0 0 0 1px var(--line)}.tabs button{box-shadow:none;background:none;white-space:nowrap}.tabs button[aria-selected=true]{background:linear-gradient(#fff,#e4e5e9);color:#111}.tv-status{justify-self:end;padding:9px 17px;border-radius:30px;background:#ffffff0b;color:var(--sub);font-size:14px}.dot{color:#5adb94;margin-right:7px}.card{min-width:0;border-radius:24px;background:var(--card);box-shadow:inset 0 1px #ffffff1a,inset 0 0 0 1px #ffffff08;padding:24px}main{max-width:1800px;padding:8px 36px 48px;margin:auto}.workspace{display:grid;grid-template-columns:380px minmax(320px,1fr) 340px;gap:24px;align-items:start}.paste-card{position:sticky;top:24px}.server-list{min-width:0;display:grid;gap:20px}.submit-panel{position:sticky;top:24px}.server{border:0;margin:0;min-width:0}.fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.line-head{display:grid;grid-template-columns:140px minmax(0,1fr) 44px;gap:12px;align-items:end}.line{margin-top:18px;padding-top:16px;border-top:1px solid var(--line)}.line-head label{margin:0}.remove-line{height:48px;padding:0}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}.actions button{flex:1}.row{display:flex;gap:12px;justify-content:space-between;align-items:center}h1{font-size:28px;margin:0 0 10px}h2{font-size:21px;letter-spacing:-.4px;margin:0}p{color:var(--sub);margin:10px 0 20px}label{display:block;font-size:14px;color:var(--sub);margin:16px 0 6px}input,textarea{width:100%;min-height:48px;border:0;border-radius:13px;padding:12px 14px;background:#0005;color:#fff;box-shadow:inset 0 1px 3px #0008,inset 0 0 0 1px #ffffff16;font-size:16px}input:focus,textarea:focus{outline:2px solid #fff;outline-offset:1px}input[type=checkbox]{width:44px;height:24px;min-height:24px;accent-color:#fff;box-shadow:none;cursor:pointer}textarea{height:310px;resize:vertical;font-family:ui-monospace,monospace;line-height:1.6}.hint,.status{font-size:14px;color:var(--sub)}.status{min-height:24px;margin-top:14px}.ok{color:#6de3a4}.no{color:#f3bf70}ul{list-style:none;padding:0;margin:14px 0 0}li{padding:10px 0;border-top:1px solid var(--line);overflow-wrap:anywhere}a{color:#fff}.summary{font-size:21px;font-weight:700;margin:14px 0 20px}.result-heading{font-size:16px;color:var(--sub);margin-top:24px;padding-top:20px;border-top:1px solid var(--line)}.password-wrap{display:flex;gap:6px}.password-wrap input{min-width:0}.password-wrap button{padding:0 10px}.show-pass{width:auto!important;min-height:44px!important;height:44px!important;box-shadow:none!important}.show-label{display:flex;align-items:center;gap:6px;margin:0;font-size:12px;white-space:nowrap}.line-url{min-width:0}#mobile-summary{display:none}.backup-workspace{display:grid;grid-template-columns:1fr 1fr;gap:24px;max-width:1180px;margin:16px auto}.checkrow{display:flex;justify-content:space-between;align-items:center;min-height:56px;font-size:16px;color:#fff;margin:0;border-bottom:1px solid var(--line)}.password-fields{display:grid;grid-template-columns:1fr 1fr;gap:14px}.file-drop{display:block;padding:32px 20px;text-align:center;border:1px dashed #ffffff50;border-radius:18px;background:#0003;cursor:pointer}.file-drop input{font-size:14px;box-shadow:none;background:none;margin-top:10px}.counts{display:flex;gap:12px;margin:20px 0}.counts div{flex:1;text-align:center;padding:14px 6px;border-radius:14px;background:#ffffff08;color:var(--sub);font-size:13px}.counts b{display:block;font-size:26px;color:#fff}.mode{position:relative;display:grid;grid-template-columns:1fr 1fr;margin:20px 0;padding:5px;border-radius:30px;background:#0005;box-shadow:inset 0 1px 3px #0008,inset 0 0 0 1px #ffffff16}.mode .thumb{position:absolute;top:5px;bottom:5px;left:5px;width:calc(50% - 5px);border-radius:24px;background:linear-gradient(#fff,#e4e5e9);transition:transform .16s ease;pointer-events:none}.mode.is-replace .thumb{transform:translateX(100%)}.mode span{position:relative;z-index:1;display:grid;place-items:center;min-height:44px;font-size:15px;font-weight:600;pointer-events:none}.mode span.active{color:#111}.mode input{position:absolute;z-index:2;inset:0;width:100%;height:100%;min-height:0;margin:0;padding:0;opacity:0;cursor:pointer}.mode:focus-within{outline:2px solid white;outline-offset:3px}.preview-line{display:flex;gap:12px;justify-content:space-between;border-top:1px solid var(--line);padding:12px 0}.badge{border-radius:20px;background:#ffffff16;padding:4px 10px;font-size:13px;white-space:nowrap}[hidden]{display:none!important}
.file-drop{padding:0;border:0;background:none}.file-select{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;width:100%;min-height:156px;border:1px dashed #ffffff3d;border-radius:18px;background:#0003;box-shadow:inset 0 1px 3px #0005;color:#fff}.file-select svg{color:#a6a7af}.file-select strong{font-size:17px;max-width:100%;overflow-wrap:anywhere}.file-select span{font-size:13px;font-weight:400;color:#a6a7af}.file-select:hover{border-color:#ffffff80;background:#ffffff08}.file-select:focus-visible{outline:3px solid white;outline-offset:3px}.import-file{margin:14px 0;width:100%;font-size:14px}input[hidden]{display:none!important}.checkrow input[type=checkbox]{appearance:none;position:relative;width:44px;height:26px;border-radius:20px;padding:0;background:#0005;box-shadow:inset 0 1px 3px #0009,inset 0 0 0 1px #ffffff20;flex:none}.checkrow input[type=checkbox]::before{content:"";position:absolute;width:18px;height:18px;left:4px;top:4px;border-radius:50%;background:#aaa;transition:transform .16s ease}.checkrow input[type=checkbox]:checked{background:linear-gradient(#fff,#ddd)}.checkrow input[type=checkbox]:checked::before{transform:translateX(18px);background:#111}
@media(min-width:600px) and (max-width:1099px){header{grid-template-columns:1fr auto;padding:24px}.tabs{grid-row:2;grid-column:1/-1}.tabs button{flex:1}main{padding:0 24px 120px}.workspace{max-width:760px;grid-template-columns:1fr;margin:auto}.paste-card{position:static}.fields{grid-template-columns:1fr 1fr}.fields>label:first-child{grid-column:1/-1}.submit-panel{position:fixed;top:auto;z-index:5;bottom:20px;left:50%;transform:translateX(-50%);width:min(760px,calc(100% - 48px));display:flex;align-items:center;gap:20px;background:#28292ce8;backdrop-filter:blur(24px);border-radius:40px;padding:14px 20px}.submit-panel .primary{width:auto;min-width:260px}.submit-panel .summary{flex:1;font-size:17px;margin:0}.submit-panel .result-heading,.submit-panel #results{display:none}textarea{height:190px}.backup-workspace{grid-template-columns:1fr;max-width:760px}}
@media(max-width:599px){header{padding:20px 16px 16px;grid-template-columns:1fr auto;gap:16px}.brand{font-size:24px}.tv-status{font-size:12px;padding:8px 10px}.tabs{grid-row:2;grid-column:1/-1;justify-content:stretch}.tabs button{flex:1;font-size:14px;padding:10px 12px}main{padding:0 16px 170px}.workspace{display:flex;flex-direction:column;gap:18px}.workspace>*{width:100%}.paste-card{position:static}.card{padding:20px;border-radius:22px}.fields{display:block}.line{background:#ffffff05;border-radius:16px;padding:14px;border:0}.line-head{grid-template-columns:1fr 44px;gap:10px}.line-url{grid-column:1/-1;grid-row:2}.remove-line{grid-column:2;grid-row:1}.line-head>label:first-child{grid-column:1;grid-row:1}textarea{height:185px}.submit-panel{position:fixed;top:auto;z-index:5;left:16px;right:16px;bottom:16px;width:auto;background:#28292cec;backdrop-filter:blur(24px);border-radius:30px;padding:16px 20px}.submit-panel .summary{font-size:16px;margin:0 0 10px}.submit-panel .result-heading,.submit-panel #results{display:none}#mobile-summary{display:block;width:100%;text-align:left;margin-bottom:18px}.backup-workspace{display:block;margin:0}.backup-workspace .card{margin-bottom:18px}.password-fields{grid-template-columns:1fr}.result-copy{display:block;background:var(--card);padding:20px;border-radius:22px;margin-top:18px}}
</style></head><body>
<header><div class="brand"><svg viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="M7 7h18L7 25h18" stroke="white" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/></svg>zmby</div><nav class="tabs" aria-label="功能"><button id="tab-add" type="button" aria-selected="true">添加服务器</button><button id="tab-backup" type="button" aria-selected="false">备份与恢复</button></nav><div class="tv-status" id="tv-status"><span class="dot">●</span>正在连接电视…</div></header>
<main><section id="add-page"><button id="mobile-summary" type="button" class="secondary" hidden>上次提交</button><form id="form" class="workspace">
<aside class="card paste-card"><h2>粘贴识别</h2><p class="hint">粘贴分享信息，自动填写账号、密码和线路。</p><button type="button" class="secondary import-file" id="choose-import-file">导入 AFuseKt 或 JSON 配置</button><input id="import-config-file" type="file" accept=".json,application/json" hidden><textarea id="paste" spellcheck="false" aria-label="服务器分享信息" placeholder="家里 NAS&#10;直连：https://emby.example.com&#10;备用：https://backup.example.com&#10;账号：myname&#10;密码：mypassword"></textarea><div class="actions"><button type="button" class="secondary" id="recognize">重新识别</button><button type="button" class="secondary" id="clear">清空</button></div><div id="notice" class="status" role="status" aria-live="polite">粘贴后自动识别，检查表单后再添加。</div></aside>
<div class="server-list"><div id="servers" class="server-list"></div><button type="button" class="secondary" id="add-server">＋ 添加另一台服务器</button></div>
<aside class="card submit-panel"><div class="summary" id="entry-count">1 台服务器 · 1 条线路</div><button id="submit" class="primary">登录并添加到电视</button><div class="result-heading">上次提交</div><ul id="results" aria-live="polite"></ul></aside></form><div id="mobile-results" class="result-copy" hidden></div></section>
<section id="backup-page" hidden><div class="backup-workspace"><section class="card"><div class="row"><h2>下载备份</h2><span id="backup-total" class="hint"></span></div><p class="hint">带走服务器与线路，换设备后可直接恢复。</p>
<div class="checkrow">服务器与线路<span class="badge">必含</span></div><label class="checkrow">账号名<input id="opt-accounts" type="checkbox" checked></label><label class="checkrow">登录令牌 · 加密<input id="opt-tokens" type="checkbox" checked></label><label class="checkrow">每台服务器的设置<input id="opt-serverSettings" type="checkbox" checked></label><label class="checkrow">应用设置<input id="opt-appSettings" type="checkbox"></label>
<div class="password-fields"><label>备份密码<input id="backup-password" type="password" autocomplete="off" placeholder="包含令牌时至少 8 位"></label><label>再输一次<input id="backup-confirm" type="password" autocomplete="off"></label></div><div id="backup-status" class="status" role="status"></div><button id="download-backup" type="button" class="primary">下载备份文件</button></section>
<section class="card"><h2>恢复到电视</h2><p class="hint">选好备份后，先预览将要恢复的服务器。</p><div class="file-drop" id="drop-zone"><button type="button" class="file-select" id="choose-restore-file"><svg viewBox="0 0 32 32" width="36" height="36" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M5 8h9l3 4h10v14H5z" stroke-linejoin="round"/><path d="M16 17v6m-3-3h6" stroke-linecap="round"/></svg><strong id="restore-file-name">选择备份文件</strong><span id="restore-file-hint">支持 .zmby、JSON，也可拖入文件</span></button><input id="restore-file" type="file" accept=".zmby,.json,application/json,application/octet-stream" hidden></div><p id="file-meta" class="hint"></p><label>备份密码<input id="restore-password" type="password" autocomplete="off"></label><div class="mode" id="restore-mode"><i class="thumb" aria-hidden="true"></i><span id="merge-mode" class="active">合并到现有</span><span id="replace-mode">全部替换</span><input id="restore-mode-value" type="range" min="0" max="1" step="1" value="0" aria-label="恢复方式" aria-valuetext="合并到现有"></div><button id="preview-backup" type="button" class="secondary">查看恢复预览</button><div class="counts"><div><b id="count-added">—</b>新增</div><div><b id="count-updated">—</b>更新线路</div><div><b id="count-skipped">—</b>相同跳过</div></div><div id="restore-servers"></div><button type="button" id="expand-preview" class="secondary" hidden></button><div id="restore-status" class="status" role="status"></div><button id="restore-backup" type="button" class="primary" disabled>恢复到电视</button></section></div></section>
<template id="server-template"><fieldset class="card server"><div class="row"><h2>服务器</h2><button type="button" class="secondary small remove-server">移除</button></div><div class="fields"><label>名称<input class="name" autocomplete="off" placeholder="例如：家里 NAS"></label><label>账号<input class="user" autocomplete="username" autocapitalize="none" spellcheck="false" required></label><div class="password-field"><label>密码</label><div class="password-wrap"><input class="pass" type="password" aria-label="密码" autocomplete="off" spellcheck="false" placeholder="无密码可留空"><button type="button" class="show-pass secondary" aria-label="显示密码" aria-pressed="false"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/></svg></button></div></div></div><div class="lines"></div><div class="actions"><button type="button" class="secondary add-line">＋ 添加线路</button></div></fieldset></template>
<template id="line-template"><div class="line"><div class="line-head"><label>线路名称<input class="line-name" autocomplete="off" placeholder="直连、备用"></label><label class="line-url">线路地址<input class="url" inputmode="url" autocomplete="off" autocapitalize="none" spellcheck="false" placeholder="https://emby.example.com:8920" required></label><button type="button" class="secondary remove-line" aria-label="移除线路">×</button></div></div></template>
<script>
        const base = location.pathname.replace(/\/${'$'}/,''), servers = document.getElementById('servers'), form = document.getElementById('form');
        const paste = document.getElementById('paste'), notice = document.getElementById('notice');

        let busy = false, revision = 0, edited = false;
        function dirty() { edited = true; revision++; setTimeout(updateCounts,0); }
        function addLine(card, data = {}) {
          const line = document.getElementById('line-template').content.firstElementChild.cloneNode(true);
          line.querySelector('.url').value = data.url || ''; line.querySelector('.line-name').value = data.name || '';
          line.querySelector('.remove-line').onclick = () => { if (card.querySelectorAll('.line').length > 1) { line.remove(); dirty(); } else { line.querySelector('.url').value = ''; line.querySelector('.line-name').value = ''; dirty(); } };
          card.querySelector('.lines').appendChild(line);
        }
        function addServer(data = {}) {
          const card = document.getElementById('server-template').content.firstElementChild.cloneNode(true);
          card.querySelector('.name').value = data.name || ''; card.querySelector('.user').value = data.user || ''; card.querySelector('.pass').value = data.pass || '';
          card.querySelector('.show-pass').onclick = e => { const button=e.currentTarget; const show=button.getAttribute('aria-pressed')!=='true';button.setAttribute('aria-pressed',String(show));button.setAttribute('aria-label',show?'隐藏密码':'显示密码');card.querySelector('.pass').type=show?'text':'password'; };
          card.querySelector('.add-line').onclick = () => { addLine(card); dirty(); };
          card.querySelector('.remove-server').onclick = () => { card.remove(); if (!servers.children.length) addServer(); dirty(); };
          for (const line of data.lines && data.lines.length ? data.lines : [{}]) addLine(card, line);
          servers.appendChild(card); return card;
        }
        function readServers() {
          return Array.from(servers.children).map(card => ({name:card.querySelector('.name').value.trim(), user:card.querySelector('.user').value.trim(), pass:card.querySelector('.pass').value,
            lines:Array.from(card.querySelectorAll('.line')).map(line => ({name:line.querySelector('.line-name').value.trim(), url:line.querySelector('.url').value.trim()}))}));
        }
        form.addEventListener('input', e => { if(e.target.closest('.server')) dirty(); updateCounts(); });
        paste.addEventListener('input', () => { revision++; });
        document.getElementById('add-server').onclick = () => { addServer(); dirty(); };
        document.getElementById('clear').onclick = () => { paste.value = ''; revision++; notice.textContent = '已清空粘贴内容，表单保留。'; };
        async function recognize() {
          const text = paste.value, request = ++revision, wasEdited = edited;
          if (busy || !text.trim()) return;
          notice.textContent = '正在识别…';
          try {
            const res = await fetch(base + '/parse', {method:'POST', body:text});
            if (!res.ok) throw new Error('识别请求失败，请重新打开电视上的完整链接');
            const list = await res.json(); if (request !== revision) return;
            if (!list.length) { notice.textContent = '未识别到线路地址，请手动填写，或粘贴包含地址和账号的信息。'; return; }
            if (!wasEdited) servers.replaceChildren();
            for (const server of list) {
              const existing = Array.from(servers.children).find(card => card.querySelector('.name').value.trim() === server.name && card.querySelector('.user').value.trim() === server.user && card.querySelector('.pass').value === server.pass);
              if (!existing) addServer(server);
              else for (const line of server.lines) {
                if (!Array.from(existing.querySelectorAll('.url')).some(input => input.value.trim().replace(/\/${'$'}/,'') === line.url.replace(/\/${'$'}/,''))) addLine(existing, line);
              }
            }
            edited = true;
            const count = list.reduce((n,s) => n + s.lines.length,0);
            notice.textContent = '已' + (wasEdited ? '追加' : '填写') + ' ' + list.length + ' 台服务器、' + count + ' 条线路，请检查账号和密码。';
          } catch(e) { if (request === revision) notice.textContent = e.message; }
        }
        paste.addEventListener('paste', () => setTimeout(recognize, 0));
        document.getElementById('recognize').onclick = recognize;
        form.onsubmit = async e => {
          e.preventDefault(); if (busy || !form.reportValidity()) return;
          const entries = readServers(); if (!entries.length) return;
          revision++; busy = true;
          const controls = Array.from(document.querySelectorAll('button,input,textarea,fieldset')); controls.forEach(el => el.disabled = true);
          const results = document.getElementById('results'); results.replaceChildren();
          document.getElementById('submit').textContent = '正在登录…';
          const pending = document.createElement('li'); pending.textContent = '正在逐条线路登录…'; results.appendChild(pending);
          try {
            const res = await fetch(base, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({servers:entries})});
            if (!res.ok) throw new Error(res.status === 400 ? '请检查线路地址和账号后重试' : '添加失败，请检查电视上的扫码页是否仍然打开');
            const list = await res.json(); results.replaceChildren();
            for (const x of list) { const li = document.createElement('li'); li.className = x.ok ? 'ok' : 'no'; li.textContent = x.label + ' · ' + x.message; results.appendChild(li); }
            if (!list.length) throw new Error('没有可添加的线路');
            if (list.every(x => x.ok)) { servers.replaceChildren(); addServer(); paste.value = ''; edited = false; notice.textContent = '已添加，可继续填写下一台服务器。'; }
          } catch(e) { results.replaceChildren(); const li = document.createElement('li'); li.className = 'no'; li.textContent = e.message; results.appendChild(li); }
          finally { busy = false; controls.forEach(el => el.disabled = expired); document.getElementById('submit').textContent = '登录并添加到电视'; updateCounts(); updateSummary(); }
        };
        addServer();

        let expired=false, bootstrapped=false, restoreText='', restoreMode='Merge', restoreReady=false, replacing=false, previewRows=[];
        function updateCounts(){ const entries=readServers(); document.getElementById('entry-count').textContent=entries.length+' 台服务器 · '+entries.reduce((n,s)=>n+s.lines.length,0)+' 条线路'; Array.from(servers.children).forEach((card,i)=>card.querySelector('h2').textContent='服务器 '+(i+1)); }
        function setTab(backup){document.getElementById('add-page').hidden=backup;document.getElementById('backup-page').hidden=!backup;document.getElementById('tab-add').setAttribute('aria-selected',!backup);document.getElementById('tab-backup').setAttribute('aria-selected',backup);location.hash=backup?'backup':'add';}
        document.getElementById('tab-add').onclick=()=>setTab(false);document.getElementById('tab-backup').onclick=()=>setTab(true);setTab(location.hash==='#backup');
        function updateSummary(){const items=Array.from(document.getElementById('results').children);const ok=items.filter(x=>x.classList.contains('ok')).length;const no=items.filter(x=>x.classList.contains('no')).length;const summary=document.getElementById('mobile-summary');summary.hidden=!items.length;summary.textContent='上次提交 · '+ok+' 条已添加'+(no?' · '+no+' 条失败':'');const copy=document.getElementById('mobile-results');copy.replaceChildren();const list=document.createElement('ul');items.forEach(x=>list.appendChild(x.cloneNode(true)));copy.appendChild(list);copy.hidden=!items.length;}
        document.getElementById('mobile-summary').onclick=()=>document.getElementById('mobile-results').scrollIntoView({behavior:'smooth'});
        async function request(path,body){const response=await fetch(base+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!response.ok)throw new Error(await response.text());return response;}
        async function heartbeat(){if(expired)return;try{const res=await fetch(base+'/ping');if(res.status===410||res.status===404){expired=true;document.getElementById('tv-status').textContent='已失效，请在电视上重新打开';document.querySelectorAll('button,input,textarea').forEach(x=>x.disabled=true);return;}if(!res.ok)return;const data=await res.json();document.getElementById('backup-total').textContent=data.serverCount+' 台服务器';document.getElementById('tv-status').textContent='● '+data.device+' · 剩余 '+Math.floor(data.remaining/60)+':'+String(data.remaining%60).padStart(2,'0');if(busy&&data.progress)document.getElementById('submit').textContent=data.progress;if(!bootstrapped){bootstrapped=true;if(data.relogin&&data.relogin.length){servers.replaceChildren();data.relogin.forEach(addServer);notice.textContent='已填入需要重新登录的服务器，请输入密码。';edited=true;updateCounts();}}}catch(e){document.getElementById('tv-status').textContent='正在重新连接电视…';}}
        document.getElementById('choose-import-file').onclick=()=>document.getElementById('import-config-file').click();
        document.getElementById('choose-restore-file').onclick=()=>document.getElementById('restore-file').click();
        document.getElementById('import-config-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>262144){notice.textContent='配置文件过大';return;}paste.value=await file.text();revision++;await recognize();};
        heartbeat();setInterval(heartbeat,5000);updateCounts();
        document.getElementById('download-backup').onclick=async()=>{const status=document.getElementById('backup-status'),button=document.getElementById('download-backup');const password=document.getElementById('backup-password').value,confirm=document.getElementById('backup-confirm').value;const options={};for(const key of ['accounts','tokens','serverSettings','appSettings'])options[key]=document.getElementById('opt-'+key).checked;if(password!==confirm){status.textContent='两次密码不一致';return;}if((options.tokens||password)&&password.length<8){status.textContent='备份密码至少需要 8 位';return;}button.disabled=true;status.textContent='正在加密备份…';try{const response=await request('/backup',{options,password,confirm});const blob=await response.blob();const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=(response.headers.get('Content-Disposition')||'').match(/filename="([^"]+)"/)?.[1]||'zmby-backup.zmby';link.click();setTimeout(()=>URL.revokeObjectURL(url),5000);status.textContent='备份已下载';document.getElementById('backup-password').value='';document.getElementById('backup-confirm').value='';}catch(e){status.textContent=e.message;}finally{button.disabled=expired;}};
        function invalidateRestore(){restoreReady=false;replacing=false;document.getElementById('restore-backup').disabled=true;document.getElementById('restore-backup').textContent='恢复到电视';document.getElementById('restore-servers').replaceChildren();for(const key of ['added','updated','skipped'])document.getElementById('count-'+key).textContent='—';}
        async function selectFile(file){invalidateRestore();if(!file)return;if(file.size>8388608){document.getElementById('restore-status').textContent='文件过大';return;}try{restoreText=await file.text();const data=JSON.parse(restoreText);const header=data.header;document.getElementById('restore-file-name').textContent=file.name;document.getElementById('restore-file-hint').textContent='点击更换备份文件';document.getElementById('file-meta').textContent=file.name+' · '+(header?new Date(header.createdAt).toLocaleString()+' · '+header.serverCount+' 台服务器 · '+(data.encryption?'已加密':'不含令牌'):'旧版服务器列表');document.getElementById('restore-status').textContent='';}catch(e){restoreText='';document.getElementById('restore-status').textContent='文件无法识别';}}
        document.getElementById('restore-file').onchange=e=>selectFile(e.target.files[0]);const drop=document.getElementById('drop-zone');drop.ondragover=e=>e.preventDefault();drop.ondrop=e=>{e.preventDefault();selectFile(e.dataTransfer.files[0]);};document.getElementById('restore-password').oninput=invalidateRestore;
        function chooseMode(mode){restoreMode=mode;invalidateRestore();document.getElementById('restore-mode').classList.toggle('is-replace',mode==='Replace');document.getElementById('restore-mode-value').value=mode==='Replace'?'1':'0';document.getElementById('restore-mode-value').setAttribute('aria-valuetext',mode==='Replace'?'全部替换':'合并到现有');document.getElementById('merge-mode').classList.toggle('active',mode==='Merge');document.getElementById('replace-mode').classList.toggle('active',mode==='Replace');}document.getElementById('restore-mode-value').oninput=e=>chooseMode(e.target.value==='1'?'Replace':'Merge');
        function drawPreview(expanded=false){const box=document.getElementById('restore-servers');box.replaceChildren();for(const row of expanded?previewRows:previewRows.slice(0,5)){const line=document.createElement('div');line.className='preview-line';const name=document.createElement('span');name.textContent=row.name+' · '+row.lines+' 条线路';const badge=document.createElement('span');badge.className='badge';badge.textContent=row.needsLogin?'需重新登录':row.action;line.append(name,badge);box.appendChild(line);}const expand=document.getElementById('expand-preview');expand.hidden=expanded||previewRows.length<=5;expand.textContent='另有 '+(previewRows.length-5)+' 台';expand.onclick=()=>drawPreview(true);}
        document.getElementById('preview-backup').onclick=async()=>{const status=document.getElementById('restore-status');if(!restoreText){status.textContent='请先选择备份文件';return;}status.textContent='正在读取备份…';try{const response=await request('/restore/preview',{file:restoreText,password:document.getElementById('restore-password').value,mode:restoreMode});const data=await response.json();for(const key of ['added','updated','skipped'])document.getElementById('count-'+key).textContent=data[key];previewRows=data.servers;drawPreview();restoreReady=true;document.getElementById('restore-backup').disabled=expired;status.textContent='请核对后恢复';}catch(e){invalidateRestore();status.textContent=e.message;}};
        document.getElementById('restore-backup').onclick=async()=>{if(!restoreReady)return;const button=document.getElementById('restore-backup'),status=document.getElementById('restore-status');if(restoreMode==='Replace'&&!replacing){replacing=true;button.textContent='再次确认全部替换';status.textContent='将删除备份里没有的服务器';return;}button.disabled=true;status.textContent='正在验证并恢复服务器…';try{await request('/restore',{file:restoreText,password:document.getElementById('restore-password').value,mode:restoreMode,confirmed:replacing});status.textContent='已恢复到电视；失效的账号可在添加服务器页签重新登录。';document.getElementById('restore-password').value='';restoreText='';restoreReady=false;document.getElementById('restore-file').value='';bootstrapped=false;heartbeat();}catch(e){status.textContent=e.message;button.disabled=expired;}};

</script></main></body></html>
    """.trimIndent()
}
